 ("all but exact rounding",      dict(governing=True, keyed=True, exact=False,rt_only=True)),
 ("ALL fixes",                   dict(governing=True, keyed=True, exact=True, rt_only=True)),
]
results={name:run(name,**kw) for name,kw in variants}
cells=sorted(results["S0 original code"])
